-- Data classification
--
-- Which columns hold protected health information, which merely identify a person, which
-- are operational, and which are secrets. The reviewer's first question about an
-- inventory is how anyone knows it is still true — so this is not a list kept beside the
-- schema. It is a table with a completeness check, and a column added later without a
-- classification fails that check rather than quietly joining the untracked set.
--
-- Applied after schema.sql. The inventory itself is generated by the view at the end.
--
-- The classes, and the line between them:
--
--   phi           Health information about a resident, or anything that identifies the
--                 resident it belongs to. A resident's name is PHI here — it is an
--                 identifier attached to a care record, which is what the term means.
--   identifying   Identifies a person who is not the patient. Staff and family contact
--                 details. Sensitive, subject to the same access control, but not PHI:
--                 a caregiver's email is not health information about a caregiver.
--   operational   Keys, timestamps, state, configuration. Reveals nothing on its own.
--   secret        Credentials. Never logged, never returned by an API, never in a backup
--                 that is less protected than the database.

CREATE TYPE data_class AS ENUM ('phi', 'identifying', 'operational', 'secret');

CREATE TABLE data_classification (
  table_name   text NOT NULL,
  column_name  text NOT NULL,
  class        data_class NOT NULL,
  note         text,
  PRIMARY KEY (table_name, column_name)
);

COMMENT ON TABLE data_classification IS
  'Source of the PHI inventory. Kept in the database rather than a document so that the
   inventory can be generated rather than maintained, and so that drift is a failing
   check rather than a discovery during review.';


-- ── facilities ─────────────────────────────────────────────────────────────────
-- A building is not a person. Nothing here is PHI.



-- ── users ──────────────────────────────────────────────────────────────────────
-- Caregivers, managers and family members. None of them is the patient, so their
-- details identify without being health information. They are still access-controlled.





-- ── staff membership and assignment ────────────────────────────────────────────
-- Who works where, and who is responsible for whom. The assignment rows are
-- operational on their own, but they are the thing access control resolves from, so
-- they are protected as tightly as what they unlock.




-- ── residents ──────────────────────────────────────────────────────────────────
-- The patient. A name attached to a care record is PHI, and so is a baseline: saying
-- someone is usually confused is a statement about their health.



-- ── family access ──────────────────────────────────────────────────────────────
-- The relation column is the subtle one: "child of resident X" says something about a
-- person's family circumstances, and it is attached to a patient record.



-- ── the care record ────────────────────────────────────────────────────────────
-- All of it. This is the reason the rest of the file exists.





-- ── medication ─────────────────────────────────────────────────────────────────



-- ── media ──────────────────────────────────────────────────────────────────────
-- The photograph is PHI. So is its path: object keys are derived from the resident, and
-- a path that leaks tells you who a stored image is of.



-- ── audit ──────────────────────────────────────────────────────────────────────
-- The audit trail records that a resident's record was touched, which is itself
-- health information — someone has a care record. It does not record what the record
-- said, and the detail column is constrained to field names rather than values.



-- ── retention ──────────────────────────────────────────────────────────────────


-- The classification table classifies itself, so the completeness check below has
-- nothing to except.


-- ════════════════════════════════════════════════════════════════════ the inventory
--
-- Generated, not written. This is what goes to the reviewer, and it cannot disagree with
-- the database because it is read from it.

CREATE VIEW phi_inventory AS
SELECT
  c.table_name,
  c.column_name,
  c.data_type,
  dc.class,
  dc.note
FROM information_schema.columns c
JOIN information_schema.tables t
       ON t.table_schema = c.table_schema AND t.table_name = c.table_name
      AND t.table_type = 'BASE TABLE'          -- views derive from these; classifying
                                               -- both would be a second list to drift
LEFT JOIN data_classification dc
       ON dc.table_name = c.table_name AND dc.column_name = c.column_name
WHERE c.table_schema = 'public'
ORDER BY (dc.class = 'phi') DESC NULLS FIRST, c.table_name, c.ordinal_position;

COMMENT ON VIEW phi_inventory IS
  'The PHI inventory for the review package. Unclassified columns sort to the top, so an
   omission is the first thing read rather than the last thing found.';


-- Every column in the schema must be classified. A new column arrives unclassified and
-- this returns it; the check below turns that into a failure rather than a footnote.
CREATE VIEW unclassified_columns AS
SELECT c.table_name, c.column_name
FROM information_schema.columns c
JOIN information_schema.tables t
       ON t.table_schema = c.table_schema AND t.table_name = c.table_name
      AND t.table_type = 'BASE TABLE'
LEFT JOIN data_classification dc
       ON dc.table_name = c.table_name AND dc.column_name = c.column_name
WHERE c.table_schema = 'public'
  AND dc.class IS NULL;
